    {"id": 52, "category": "شیمی دهم (آب و محلول‌ها)", "question": "ترتیب انحلال گازهای CO₂، NO، O₂ و N₂ در آب؟", "answer": "CO₂ > NO > O₂ > N₂ (کربن دی‌اکسید با آب واکنش داده و بیشترین انحلال را دارد؛ نیتروژن کمترین)."},
    {"id": 53, "category": "شیمی دهم (آب و محلول‌ها)", "question": "پدیده اسمز و اسمز معکوس چیست و چه کاربردی دارد؟", "answer": "اسمز: عبور خودبه‌خودی آب از غشای نیمه‌تراوا از محلول رقیق به غلیظ | اسمز معکوس: اعمال فشار بر محلول غلیظ برای عبور آب به سمت رقیق (کاربرد در شیرین‌سازی آب دریا)."},
    {"id": 54, "category": "شیمی دهم (آب و محلول‌ها)", "question": "چه موادی با روش تقطیر و اسمز معکوس از آب جدا نمی‌شوند؟", "answer": "میکروب‌ها با تقطیر و اسمز معکوس به تنهایی حذف قطعی نمی‌شوند و نیاز به کلرزنی دارند؛ ترکیبات آلی فرار نیز با تقطیر جدا نمی‌شوند."},

    # ==================== پایه یازدهم - هدایای زمینی و نفت ====================
    {"id": 55, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "چند درصد عناصر جدول تناوبی فلز هستند و تنها فلز و نافلز مایع کدامند؟", "answer": "بیش از ۸۰٪ عناصر جدول فلزند؛ تنها فلز مایع جیوه (Hg) و تنها نافلز مایع برم (Br₂) است."},
    {"id": 56, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "عناصر گروه ۱۴ و خواص آن‌ها از نظر فلز، نافلز و شبه‌فلز؟", "answer": "کربن C (نافلز) | سیلیسیم Si و ژرمانیم Ge (شبه‌فلز نیم‌رسانا) | قلع Sn و سرب Pb (فلز). تعداد شبه‌فلز با فلز در این گروه برابر است (۲ به ۲)."},
    {"id": 57, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "روند شعاع اتمی در جدول تناوبی چگونه است؟", "answer": "در هر گروه از بالا به پایین افزایش می‌یابد؛ در هر دوره از چپ به راست به دلیل افزایش بار مؤثر هسته کاهش می‌یابد (قلیایی‌ها بزرگترین و هالوژن‌ها کوچکترین)."},
    {"id": 58, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "شرایط واکنش هالوژن‌ها (F₂, Cl₂, Br₂, I₂) با گاز هیدروژن؟", "answer": "F₂: در دمای ۲۰۰- درجه سلسیوس حتی در تاریکی انفجاری | Cl₂: در دمای اتاق به آرامی | Br₂: در دمای ۲۰۰°C | I₂: در دمای بالای ۴۰۰°C به کندی."},
    {"id": 59, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "ویژگی‌های برجسته طلا (Au) در صنعت و فناوری؟", "answer": "چکش‌خوار و بسیار نرم، قابلیت تورق فوق‌العاده (ساخت نخ و ورقه‌های بسیار نازک)، رسانایی الکتریکی عالی و حفظ آن در دماهای مختلف، عدم واکنش با هواکره، بازتاب بالای پرتوهای خورشیدی."},
    {"id": 60, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "معادن مشهور طلای ایران و پسماند تولید یک حلقه طلا؟", "answer": "معادن موته (اصفهان) و زرشوران (آذربایجان غربی)؛ برای ساخت ۱ حلقه طلا حدود ۳ تن پسماند معدنی تولید می‌شود."},
    {"id": 61, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "واکنش ترمیت و کاربرد اصلی آن چیست؟", "answer": "واکنش بسیار گرماده 2Al + Fe₂O₃ -> Al₂O₃ + 2Fe(l)؛ آهن مذاب تولید شده برای جوش دادن خطوط راه‌آهن استفاده می‌شود."},
    {"id": 62, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "گیاه‌پالایی چیست و استخراج کدام فلزات با آن مقرون‌به‌صرفه است؟", "answer": "کاشت گیاهانی که فلزات را از خاک جذب می‌کنند و سپس سوزاندن آن‌ها؛ استخراج طلا (Au) و مس (Cu) مقرون‌به‌صرفه است اما روی (Zn) و نیکل (Ni) نه."},
    {"id": 63, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "هر بشکه نفت خام چند لیتر است و عنصر اصلی سازنده آن چیست؟", "answer": "معادل ۱۵۹ لیتر؛ عنصر اصلی کربن (C) است و حدود ۵۰٪ نفت خام به عنوان سوخت مصرف می‌شود."},
    {"id": 64, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "فرمول شیمیایی گریس و وازلین چیست؟", "answer": "گریس: C₁₈H₃₈ (آلکان ۱۸ کربنه) | وازلین: C₂₅H₅₂ (آلکان ۲۵ کربنه)."},
    {"id": 65, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "سوخت فندک چیست و چهار آلکان اول چه حالتی دارند؟", "answer": "سوخت فندک گاز بوتان (C₄H₁₀) است؛ چهار آلکان اول (متان، اتان، پروپان، بوتان) در دمای اتاق گاز هستند."},
    {"id": 66, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "معرف شناسایی پیوند دوگانه در آلکن‌ها چیست؟", "answer": "محلول برم در آب (آب برم) که قرمز-نارنجی است؛ در واکنش با آلکن پیوند دوگانه شکسته و رنگ محلول کاملاً بی‌رنگ می‌شود."},
    {"id": 67, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "ساده‌ترین آلکین چیست و چه کاربردی دارد؟", "answer": "اتین یا استیلن (C₂H₂)؛ از سوختن آن با اکسیژن شعله بسیار داغ برای جوشکاری و برشکاری فلزات ایجاد می‌شود."},
    {"id": 68, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "ساختار و کاربرد نفتالن چیست؟", "answer": "هیدروکربن آروماتیک با دو حلقه بنزنی جوش‌خورده به فرمول C₁₀H₈ دارای ۵ پیوند دوگانه؛ کاربرد به عنوان ضد بید برای فرش و لباس."},
    {"id": 69, "category": "شیمی یازدهم (هدایای زمینی و نفت)", "question": "علت انفجار در معادن زغال‌سنگ چیست و راه پیشگیری آن؟", "answer": "تجمع گاز متان (CH₄) به بیش از ۵٪ حجم هوا؛ استفاده از تهویه مناسب و مداوم هوا در تونل‌های معدن."},

    # ==================== پایه یازدهم - غذا و گرماشیمی ====================
    {"id": 70, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "تفاوت دما و گرما چیست و یکای آن‌ها؟", "answer": "دما: معیاری برای میانگین انرژی جنبشی ذرات (وابسته به مقدار نیست، یکا K یا °C) | گرما: انرژی مبادله شده ناشی از اختلاف دما (وابسته به مقدار و دما، یکا J یا kJ)."},
    {"id": 71, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "مقایسه ظرفیت گرمایی ویژه آب با اتانول، نقره و طلا؟", "answer": "آب (۴.۱۸) > اتانول (۲.۴۲) > نقره (۰.۲۴) > طلا (۰.۱۲۸ J/g.°C). آب بالاترین ظرفیت گرمایی ویژه را دارد."},
    {"id": 72, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "اساس کار بسته‌های گرمازا و سرمازای ورزشی چیست؟", "answer": "انحلال ترکیبات یونی؛ بسته سرمازا انحلال گرماگیر آمونیوم نیترات (NH₄NO₃) و بسته گرمازا انحلال گرماده کلسیم کلرید (CaCl₂)."},
    {"id": 73, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "مقایسه ارزش سوختی چربی، پروتئین و کربوهیدرات؟", "answer": "ارزش سوختی چربی (۳۸ kJ/g) بیش از دو برابر پروتئین (۱۷ kJ/g) و کربوهیدرات (۱۷ kJ/g) است."},
    {"id": 74, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "قانون هس چیست و چه زمانی به کار می‌رود؟", "answer": "آنتالپی یک واکنش مجموع آنتالپی مراحلی است که به واکنش نهایی منجر می‌شوند؛ برای واکنش‌هایی که انجام مستقیم آن‌ها کند، خطرناک یا همراه با فرآورده‌های جانبی است."},
    {"id": 75, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "رادیکال چیست و آنتی‌اکسیدان‌ها چگونه عمل می‌کنند؟", "answer": "گونه فعال و ناپایدار با الکترون جفت‌نشده (منفرد) که به بافت‌ها آسیب می‌زند؛ آنتی‌اکسیدان‌ها (مانند لیکوپن در هندوانه و گوجه) رادیکال‌ها را به دام می‌اندازند."},
    {"id": 76, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "فرمول و ساختار لیکوپن چیست؟", "answer": "یک هیدروکربن سیرنشده با فرمول C₄₀H₅₆ دارای ۱۳ پیوند دوگانه کربن-کربن (C=C)."},
    {"id": 77, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "بنزوئیک اسید چیست و در چه میوه‌هایی وجود دارد؟", "answer": "یک اسید کربوکسیلیک آروماتیک به فرمول C₆H₅COOH که نگه‌دارنده مواد غذایی است و به طور طبیعی در تمشک و توت‌فرنگی یافت می‌شود."},
    {"id": 78, "category": "شیمی یازدهم (غذا و گرماشیمی)", "question": "ساختار شیمیایی کلسترول چیست؟", "answer": "یک الکل سیرنشده سنگین در غذاهای جانوری که رسوب اضافی آن در دیواره رگ‌ها موجب گرفتگی و بیماری قلبی می‌شود."},

    # ==================== پایه یازدهم - پلیمرها و سنتز ====================
    {"id": 79, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "تفاوت پلی‌اتیلن سبک (LDPE) و سنگین (HDPE)؟", "answer": "LDPE: شاخه‌دار، چگالی کمتر، شفاف، انعطاف‌پذیر (کیسه پلاستیکی) | HDPE: بدون شاخه، چگالی بیشتر، کدر، سخت و محکم (دبه آب، بطری شیر). هر دو چگالی کمتر از آب دارند."},
    {"id": 80, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "مونومر، ویژگی‌ها و کاربرد تفلون چیست؟", "answer": "مونومر تترافلوئورواتن (CF₂=CF₂)؛ نقطه ذوب بالا، مقاومت حرارتی عالی، از نظر شیمیایی بی‌اثر و نچسب، نامحلول در حلال‌ها؛ کاربرد در ظروف نچسب و نخ دندان."},
    {"id": 81, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "کاربردهای پلیمرهای PVC، پلی‌پروپن و پلی‌استایرن؟", "answer": "PVC: کیسه خون و لوله‌های آب | پلی‌پروپن (PP): سرنگ و طناب | پلی‌استایرن (PS): ظروف یکبار مصرف."},
    {"id": 82, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "بنزآلدهید، دارچین و ۲-هپتانون حاوی چه گروه‌های عاملی هستند؟", "answer": "بنزآلدهید: آلدهید آروماتیک در بادام | دارچین: آلدهید آروماتیک (C₉H₈O) | ۲-هپتانون: کتون در میخک."},
    {"id": 83, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "استرهای مسئول بوی میوه‌های آناناس، موز، سیب و انگور؟", "answer": "آناناس: اتیل بوتانوآت | موز: پنتیل اتانوآت | سیب: متیل بوتانوآت | انگور: اتیل هپتانوآت."},
    {"id": 84, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "ویتامین C و ویژگی‌های ساختاری آن؟", "answer": "فرمول C₆H₈O₆؛ دارای ۴ گروه عاملی الکلی و ۱ گروه استری؛ محلول در آب و مصرف بیش از حد آن دفع می‌شود."},
    {"id": 85, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "کولار (Kevlar) چیست و مقاومت آن در مقایسه با فولاد؟", "answer": "یک پلی‌آمید ساختگی از واکنش دی‌اسید و دی‌آمین که ۵ برابر فولاد هم‌جرم خود مقاوم‌تر است؛ کاربرد در جلیقه ضدگلوله، تایر خودرو، قایق بادبانی."},
    {"id": 86, "category": "شیمی یازدهم (پلیمرها و سنتز)", "question": "پلی‌لاکتیک اسید (PLA) چیست و چگونه تجزیه می‌شود؟", "answer": "پلیمر سبز زیست‌تخریب‌پذیر تهیه شده از نشاسته ذرت و سیب‌زمینی؛ در طبیعت ظرف چند ماه به CO₂ و H₂O تجزیه می‌شود."},

    # ==================== پایه دوازدهم - پاک‌کننده‌ها و اسید/باز ====================
    {"id": 87, "category": "شیمی دوازدهم (اسید و باز و پاک‌کننده‌ها)", "question": "تفاوت صابون جامد و مایع در نوع باز مصرفی؟", "answer": "صابون جامد: نمک سدیم اسید چرب (RCOONa با استفاده از سود NaOH) | صابون مایع: نمک پتاسیم یا آمونیوم (RCOOK با استفاده از پتاس KOH یا آمونیاک)."},
    {"id": 88, "category": "شیمی دوازدهم (اسید و باز و پاک‌کننده‌ها)", "question": "علت کاهش قدرت پاک‌کنندگی صابون در آب سخت چیست؟", "answer": "یون‌های کلسیم (Ca²⁺) و منیزیم (Mg²⁺) موجود در آب سخت با صابون واکنش داده و رسوب سفید نامحلول (RCOO)₂Ca تشکیل می‌دهند."},
    {"id": 89, "category": "شیمی دوازدهم (اسید و باز و پاک‌کننده‌ها)", "question": "مزیت پاک‌کننده غیرصابونی (سولفونات) بر صابون سنتی؟", "answer": "از مواد پتروشیمیایی تهیه می‌شود و با یون‌های Ca²⁺ و Mg²⁺ آب سخت رسوب تشکیل نمی‌دهد و در آب سخت هم به خوبی کف می‌کند."},
    {"id": 90, "category": "شیمی دوازدهم (اسید و باز و پاک‌کننده‌ها)", "question": "صابون مراغه چه ویژگی‌هایی دارد؟", "answer": "بیش از ۱۵۰ سال قدمت، تهیه از دنبه گوسفند و سود سوزآور بدون افزودنی شیمیایی، خصلت بازی و مناسب برای موهای چرب (تولید سالانه ۲۰۰ تن)."},
    {"id": 91, "category": "شیمی دوازدهم (اسید و باز و پاک‌کننده‌ها)", "question": "مخلوط پاک‌کننده لوله‌های صنعتی حاوی چه موادی است و واکنش آن؟", "answer": "مخلوط پودر آلومینیوم (Al) و سدیم هیدروکسید (NaOH): 2Al + 2NaOH + 6H₂O -> 2NaAl(OH)₄ + 3H₂؛ اثر پاک‌کنندگی به دلیل گاز H₂، گرمادهی شدید و صابونی شدن چربی‌ها با سود است."},
